brief.key_terms_glossary:
[{'term': 'Bausparsumme', 'definition': 'Der vertraglich vereinbarte Gesamtwert des Bausparvertrags, der sich aus dem Sparanteil und dem späteren Darlehensanteil zusammensetzt.'}
 {'term': 'Zuteilung', 'definition': 'Der Zeitpunkt, an dem ein Vertrag die nötige Bewertung erreicht hat und der Kunde das Darlehen zu den festgesetzten Zinsen beanspruchen kann.'}
 {'term': 'Bewertungszahl', 'definition': 'Ein Punktwert, der basierend auf der Bausparsumme und den geleisteten Einzahlungen berechnet wird, um den Rang in der Zuteilungsliste zu bestimmen.'}
 {'term': 'Sondertilgung', 'definition': 'Die Möglichkeit, zusätzlich zu den regelmäßigen Raten außerplanmäßige Rückzahlungen des Darlehens zu leisten, was bei unseren Bauspardarlehen jederzeit kostenfrei möglich ist.'}]
